INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(13401, 'Psalms 34:1', 'Psalms', 34, 1, '&nbsp;هر وخت به زۀ د مالِک خُدائ ثناء صِفت کوم، زۀ به په خپله ژبه ټول عمر د هغۀ ثناء صِفت کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13402, 'Psalms 34:2', 'Psalms', 34, 2, '&nbsp;په مالِک خُدائ به زما روح فخر کوى، بې‌وسه خلق دې خوشحالى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13403, 'Psalms 34:3', 'Psalms', 34, 3, '&nbsp;راځئ ما سره د مالِک خُدائ لوئى بيان کړئ، او په شريکه د هغۀ نوم ته لوئى ورکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13404, 'Psalms 34:4', 'Psalms', 34, 4, '&nbsp;نو هغه ما ته جواب راکوى کله چې زۀ د مالِک خُدائ نه سوال کوم، زۀ يې د خپلې هرې يرې نه خلاص کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13405, 'Psalms 34:5', 'Psalms', 34, 5, '&nbsp;څوک چې په هغۀ توکل کوى نو د خوشحالۍ نه ځليږى، مختورن به نۀ وى او نۀ به شرميږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13406, 'Psalms 34:6', 'Psalms', 34, 6, '&nbsp;مالِک خُدائ زما عاجز دُعا واورېدله، د خپلو ټولو تکليفونو نه هغۀ زۀ خلاص کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13407, 'Psalms 34:7', 'Psalms', 34, 7, '&nbsp;د مالِک خُدائ فرښتې د هغه خلقو نه ګېرچاپېره وى، بچ ساتى هغوئ څوک چې د مالِک خُدائ نه په ويره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13408, 'Psalms 34:8', 'Psalms', 34, 8, '&nbsp;د مالِک خُدائ ښۀ والے وآزمايئ او وګورئ چې هغه څومره ښۀ دے. څوک چې د هغۀ نه پناه غواړى هغه بختور دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13409, 'Psalms 34:9', 'Psalms', 34, 9, '&nbsp;اے ټولو مقدسينو د مالِک خُدائ نه يره کوئ، د هغوئ به د هيڅ څيز کمے نۀ وى څوک چې ترې نه يره کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13410, 'Psalms 34:10', 'Psalms', 34, 10, '&nbsp;د زمرى بچى به اوږى او کمزورى شى، خو د چا چې په مالِک خُدائ باندې توکل وى هغه به د هيڅ څيز محتاجه نۀ شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13411, 'Psalms 34:11', 'Psalms', 34, 11, '&nbsp;راځئ، زما بچو، ما ته غوږ شئ، نو تاسو به د مالِک خُدائ د يرې نه خبر کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13412, 'Psalms 34:12', 'Psalms', 34, 12, '&nbsp;په تاسو کښې څوک داسې شته چې ډېر اوږد عمر غواړى ښې او نېک بختې ورځې ليدل غواړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13413, 'Psalms 34:13', 'Psalms', 34, 13, '&nbsp;نو په خپلې ژبې سره بد مۀ وايئ او په خپلو شونډو سره دروغ مۀ وايئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13414, 'Psalms 34:14', 'Psalms', 34, 14, '&nbsp;ښۀ کوئ او د بدو نه ځان ساتئ، امن قائم ساتئ او د هغې کوشش کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13415, 'Psalms 34:15', 'Psalms', 34, 15, '&nbsp;د مالِک خُدائ نظر په صادقانو وى او د هغوئ فريادونه اورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13416, 'Psalms 34:16', 'Psalms', 34, 16, '&nbsp;خو مالِک خُدائ د هغوئ خلاف وى څوک چې بد کارونه کوى، او د هغوئ نام و نشان د زمکې د مخ نه ورَکَوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13417, 'Psalms 34:17', 'Psalms', 34, 17, '&nbsp;نو مالِک خُدائ يې اورى کله چې صادقان فرياد کوى، او د ټولو مصيبتونو نه ورته خلاصون ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13418, 'Psalms 34:18', 'Psalms', 34, 18, '&nbsp;مالِک خُدائ هغه چا ته ورنزدې دے څوک چې غمژن وى او هغوئ ته خلاصون ورکوى څوک چې بې‌حوصلې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13419, 'Psalms 34:19', 'Psalms', 34, 19, '&nbsp;کۀ هر څو يو صادق انسان د مصيبتونو سره مخ شى، خو مالِک خُدائ د هغه ټولو نه هغۀ ته خلاصون ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13420, 'Psalms 34:20', 'Psalms', 34, 20, '&nbsp;نو مالِک خُدائ د هغۀ د ټولو اندامونو حفاظت کوى، چې کله به د هغوئ نه يو هم مات نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13421, 'Psalms 34:21', 'Psalms', 34, 21, '&nbsp;بدعمله به په خپله بدکارۍ ټول تباه شى، او د صادقانو دشمن ته به سزا ورکړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13422, 'Psalms 34:22', 'Psalms', 34, 22, '&nbsp;خو مالِک خُدائ به خپلو خادِمانو ته خلاصون ورکوى، هيڅ يو به هم مجرم نۀ شى څوک چې د هغۀ نه پناه غواړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13423, 'Psalms 35:1', 'Psalms', 35, 1, '&nbsp;اے مالِکه خُدايه، د هغوئ مخالفت وکړه، څوک چې زما مخالفت کوى، هغوئ سره جنګ وکړه څوک چې زما خلاف جنګ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13424, 'Psalms 35:2', 'Psalms', 35, 2, '&nbsp;خپل ډال زغره دې راواخله، راپاڅه او زما مدد له راشه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13425, 'Psalms 35:3', 'Psalms', 35, 3, '&nbsp;د هغوئ خلاف څوک چې ما پسې دى خپله تُوره او نېزه دې راواخله. چې تۀ زما خلاصونکے يې خُدايه، په دې ما مطمئن کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13426, 'Psalms 35:4', 'Psalms', 35, 4, '&nbsp;څوک چې ما قتلول غواړى بې‌عزته او شرمنده دې شى، څوک چې ما بربادول غواړى ناکام او شرمنده دې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13427, 'Psalms 35:5', 'Psalms', 35, 5, '&nbsp;هغوئ دې په هوا کښې لکه د بوسو په شان والوځى، او د مالِک خُدائ فرښته دې هغوئ وزغلوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13428, 'Psalms 35:6', 'Psalms', 35, 6, '&nbsp;د هغوئ لار دې تيارۀ او ښوئېدونکې شى، فرښته د مالِک خُدائ دې ورپسې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13429, 'Psalms 35:7', 'Psalms', 35, 7, '&nbsp;بې‌سببه هغوئ ما ته اېښودى دى دامونه بې‌سببه يې زما د نيولو دپاره کوهے کنستے دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13430, 'Psalms 35:8', 'Psalms', 35, 8, '&nbsp;بربادى دې ناګهانه ورباندې راشى ما ته اېښى جال کښې دې په خپله ګېر شى، ما ته چې کنستې ده په هم هغه کنده کښې دې ګېر شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13431, 'Psalms 35:9', 'Psalms', 35, 9, '&nbsp;نو بيا زۀ به د مالِک خُدائ خوشحالى کوم. چې هغه مې بچ کوى نو زۀ به خوشحالى کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13432, 'Psalms 35:10', 'Psalms', 35, 10, '&nbsp;زما ټول ځان به ثنا وائى ستا، ”مالِکه خُدايه بل څوک دے لکه ستا؟ د زورَورو نه کمزورى څوک بچ کولے شى. حاجتمند او مسکينان څوک د شوکمارو نه بچ کولے شى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13433, 'Psalms 35:11', 'Psalms', 35, 11, '&nbsp;بې‌رحمه ګواهانو په دروغو وکړه ګواهى په ما، چې بلکل ترې خبر نۀ يم هغه اِلزامونه يې ولګول په ما.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13434, 'Psalms 35:12', 'Psalms', 35, 12, '&nbsp;هغوئ د ښو په بدل کښې بد راسره کوى، او زۀ په غم باندې اخته يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13435, 'Psalms 35:13', 'Psalms', 35, 13, '&nbsp;خو ما د هغوئ په بيمارۍ، د غم جامې واچولې روژه دار شوم. او په روژه نيولو او دُعا کولو د دوئ دپاره عاجز شوم، ما د عاجزۍ نه په دُعا کښې سر ټيټ نيولے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13436, 'Psalms 35:14', 'Psalms', 35, 14, '&nbsp;زۀ داسې خفه وم لکه څنګه چې څوک وى، خفه په غم د دوستانو يا د ورور. داسې مې سر ټيټ کړے وو لکه څنګه څوک ‎چې وير کوى د خپلې مور.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13437, 'Psalms 35:15', 'Psalms', 35, 15, '&nbsp;خو دوئ ټول خوشحاله وُو چې راغلے وو غم په ما، په ملنډو سره راټول شوى وُو دوئ خلاف زما، هغه کسانو راباندې حمله وکړه چې وُو اجنبيان او دوئ بې‌عزتى کوى په ما پورې مدام.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13438, 'Psalms 35:16', 'Psalms', 35, 16, '&nbsp;لکه د بدکارانو غوندې په بې‌رحمۍ سره يې وکړله ما پورې خندا، دوئ د نفرت نه خپل غاښونه وچيچل په ما.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13439, 'Psalms 35:17', 'Psalms', 35, 17, '&nbsp;اے مالِکه خُدايه، ترڅو پورې به تۀ دوئ ته ګورې؟ ما د دوئ د خطرناکو حملو نه بچ کړه، زما ژوند د دې زمرو نه بچ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13440, 'Psalms 35:18', 'Psalms', 35, 18, '&nbsp;نو بيا به زۀ ستا شُکر په لويه ډله کښې ادا کړم. زۀ به په ټولو خلقو کښې ستا ثناء صِفت وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13441, 'Psalms 35:19', 'Psalms', 35, 19, '&nbsp;مۀ پرېږده چې زما دشمنان زما په شکست باندې خوشحاله شى، مۀ پرېږده هغوئ چې نفرت کوى له ما چې په غم زما خوشحاله شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13442, 'Psalms 35:20', 'Psalms', 35, 20, '&nbsp;د خېر خبرې نۀ کړى د شر خبرې کوى، وائى دروغ د هغو پسې څوک چې ژوند په امن کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13443, 'Psalms 35:21', 'Psalms', 35, 21, '&nbsp;هغوئ په زوره د واه واه چغې وهى، وائى چې، ”مونږ په خپلو سترګو ليدلے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13444, 'Psalms 35:22', 'Psalms', 35, 22, '&nbsp;تا وليدل په خپله، مالِکه خُدايه، مۀ چپ کېږه، اے مالِکه خُدايه، اوس ما مۀ پرېږده،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13445, 'Psalms 35:23', 'Psalms', 35, 23, '&nbsp;راپاڅه، تۀ راپاڅه او زما دفاع وکړه، زما دپاره وکالت وکړه، زما پاکه خُدايه او زما مالِکه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13446, 'Psalms 35:24', 'Psalms', 35, 24, '&nbsp;مالِکه خُدايه، زما خُدايه د خپل عدالت په مطابق زما د بې‌ګناهۍ اعلان وکړه، چې په مصيبت کښې په ما خوشحالى وکړى زما دشمنان مۀ پرېږده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13447, 'Psalms 35:25', 'Psalms', 35, 25, '&nbsp;چې هغوئ په زړۀ کښې دا ونۀ وائى خپل، ”ګورئ هغه وشول څۀ چې مونږ غوښتل.“ او دوئ اوس نۀ شى وئيلے چې، ”دے مونږ‎ ژوندے تير کړو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13448, 'Psalms 35:26', 'Psalms', 35, 26, '&nbsp;څوک چې زما په تکليفونو خوشحاليږى هغوئ دې خوار شى او ودې شرميږى، څوک چې خپل ځان زما دپاسه کوى په بې‌شرمۍ او په بې‌عزتۍ کښې دې پټ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13449, 'Psalms 35:27', 'Psalms', 35, 27, '&nbsp;څوک چې زما طرفدارۍ له راشى نو هغوئ له لويه خوشحالى ورکړه، هغوئ دې تل د مالِک خُدائ ثناء صِفت ادا کوى څوک چې د خپل خِدمتګار په خير باندې ‎پُراَمنه خوشحالى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13450, 'Psalms 35:28', 'Psalms', 35, 28, '&nbsp;نو زۀ به په ژبه ستا صداقت بيانوم، ټوله ورځ به زۀ ستا ثناء صِفت کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13451, 'Psalms 36:1', 'Psalms', 36, 1, '&nbsp;د ګناه وهم بدکارو ته په زړۀ کښې لمسون کوى. هغوئ بلکل د خُدائ پاک نه يره نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13452, 'Psalms 36:2', 'Psalms', 36, 2, '&nbsp;هغوئ په خپل نظر کښې ځان دوکه کوى، هغوئ ته پته نۀ لګى چې په خپله څومره بدکاره دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13453, 'Psalms 36:3', 'Psalms', 36, 3, '&nbsp;دوئ په ژبه د دوکې او د بدۍ خبرې کوى. هغوئ کار د عقل او ښۀ عمل نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13454, 'Psalms 36:4', 'Psalms', 36, 4, '&nbsp;تر دې چې په خپل کټ کښې بدې منصوبې جوړوى. د بدکارانو په لاره تلل کوى د دوئ ارادې ښې نۀ دى. او د بدۍ نه مخ نۀ اړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13455, 'Psalms 36:5', 'Psalms', 36, 5, '&nbsp;مالِکه خُدايه، ستا ابدى مينه آسمانونو ته رسيږى، او ستا وفادارى د وريځو نه بره رسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13456, 'Psalms 36:6', 'Psalms', 36, 6, '&nbsp;ستا رښتينوالے لکه د لويو غرونو په شان، ستا اِنصاف لکه د سمندر د ژوروالى په شان، اے مالِکه خُدايه تۀ خيال ساتې د انسان او هم د ځناورو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13457, 'Psalms 36:7', 'Psalms', 36, 7, '&nbsp;خُدايه پاکه، ستا رښتينې او ابدى مينه څومره قيمتى ده. ټول انسانان ستا په وزرو کښې پناه اخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13458, 'Psalms 36:8', 'Psalms', 36, 8, '&nbsp;معمور به کړې هغوئ په پرېمانه مېلمستيا د خپل کور، او تۀ به هغوئ د خپل برکتونو د درياب نه کړې معمور.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13459, 'Psalms 36:9', 'Psalms', 36, 9, '&nbsp;خو تۀ د ژوندون سرچينه يې، په کوم نُور چې مونږ ليدل کوُو تۀ هغه نُور يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13460, 'Psalms 36:10', 'Psalms', 36, 10, '&nbsp;خپل ابدى رحمت دې په هغوئ نازل کړه څوک چې تا سره مينه کوى، او خپل خلاصون ورکړه هغوئ ته څوک چې صادقان دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13461, 'Psalms 36:11', 'Psalms', 36, 11, '&nbsp;مۀ پرېږده چې ما د پښو لاندې کړى مغروران، مۀ پرېږده چې ما وشړى بدکاران.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13462, 'Psalms 36:12', 'Psalms', 36, 12, '&nbsp;ګوره، هغوئ چې بد کوى او بدکاران دى څنګه راوغورزېدل، د بيا پاڅېدو نۀ دى سر د لاندې راوغورزېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13463, 'Psalms 37:1', 'Psalms', 37, 1, '&nbsp;د بدکارانو په حقله ځان مۀ پرېشانوه، او د ګناهګارانو کارونو ته نيت مۀ بدوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13464, 'Psalms 37:2', 'Psalms', 37, 2, '&nbsp;ځکه دوئ به اوچ شى د واښو په شان، او شى به مړاوى د بوټو شنو په شان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13465, 'Psalms 37:3', 'Psalms', 37, 3, '&nbsp;په مالِک خُدائ توکل وکړه او نېکى کوه، نو په زمکه باندې په امن سره ژوندون کوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13466, 'Psalms 37:4', 'Psalms', 37, 4, '&nbsp;په مالِک خُدائ کښې خوشحاله اوسه، نو هغه به پوره کړى ستا د زړۀ ارمانونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13467, 'Psalms 37:5', 'Psalms', 37, 5, '&nbsp;هر څۀ چې تۀ کوې هغه خپل مالِک خُدائ ته وسپاره، په هغۀ يقين لره هغه به شى ستا مددګاره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13468, 'Psalms 37:6', 'Psalms', 37, 6, '&nbsp;هغه به ستا رښتينوالے لکه د سحر هسې روښانه کړى، او تا سره اِنصاف به لکه د غرمې د نمر هسې روښانه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13469, 'Psalms 37:7', 'Psalms', 37, 7, '&nbsp;د مالِک خُدائ په وړاندې چپ ودرېږه، او په صبر سره د هغۀ فېصلو ته انتظار کوه، او د بدکارانو په کاميابۍ او منصوبو مۀ خفه کېږه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13470, 'Psalms 37:8', 'Psalms', 37, 8, '&nbsp;تۀ قهر او غصه مۀ کوه او مۀ خفه کېږه، دا به صرف تا د نقصان په طرف پرېږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13471, 'Psalms 37:9', 'Psalms', 37, 9, '&nbsp;ځکه چې تباه به شى بدکاران، څوک چې په مالِک خُدائ لرى ايمان، دوئ به شى ضرور د زمکې وارثان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13472, 'Psalms 37:10', 'Psalms', 37, 10, '&nbsp;په لږ وخت کښې به فنا شى بدکاران، تاسو به يې لټون کوئ خو پېدا به نۀ شى بدکاران.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13473, 'Psalms 37:11', 'Psalms', 37, 11, '&nbsp;د زمکې وارثان به جوړ شى عاجزان، په خوشحالۍ سره به اوسيږى په امان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13474, 'Psalms 37:12', 'Psalms', 37, 12, '&nbsp;بدکاران د صادقانو خلاف منصوبې جوړوى او د غصې نه ورته خپل غاښونه چيچى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13475, 'Psalms 37:13', 'Psalms', 37, 13, '&nbsp;مالِک خُدائ شريرانو پورې خاندى، ځکه چې هغه د دوئ د قضا ورځ وينى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13476, 'Psalms 37:14', 'Psalms', 37, 14, '&nbsp;راکاږى ليندې، خپله تُوره راوباسى بدکاران، ترڅو چې پرې مړۀ کړى غريبان او مظلومان، او چې مړۀ کړى هغوئ څوک دى صادقان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13477, 'Psalms 37:15', 'Psalms', 37, 15, '&nbsp;خو په خپلو تُورو به سورې شى هم د دوئ زړونه او د دوئ ليندې به ماتې شينه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13478, 'Psalms 37:16', 'Psalms', 37, 16, '&nbsp;د يو صادق چې لږ مال او دولت وى، د بدعملو د ډېر دولت نه به قيمتى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13479, 'Psalms 37:17', 'Psalms', 37, 17, '&nbsp;او مالِک خُدائ به د بدعملو زور ختم کړى، خو د صادقانو به حفاظت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13480, 'Psalms 37:18', 'Psalms', 37, 18, '&nbsp;هر وخت د مالِک خُدائ د نېکانو په ژوندون باندې نظر وى، او هغوئ ته به هغه ميراث ورکړے شى چې ابدى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13481, 'Psalms 37:19', 'Psalms', 37, 19, '&nbsp;په وخت د مصيبت کښې به هغوئ شرمنده نۀ شى، او دا چې د قحط په ورځو کښې به هغوئ ماړۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13482, 'Psalms 37:20', 'Psalms', 37, 20, '&nbsp;خو بدکاران به فنا شى، او د مالِک خُدائ دشمنان به لکه د صحرا د ګلونو په شان ختم شى، او لکه د لوګى په شان به د نظر نه فنا شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13483, 'Psalms 37:21', 'Psalms', 37, 21, '&nbsp;قرض اخلى او هيڅکله يې نۀ واپس کوى بدکاران، خو ورکوى خير خېرات په سخاوت سره صادقان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13484, 'Psalms 37:22', 'Psalms', 37, 22, '&nbsp;مالِک خُدائ چې چا ته برکت ورکړى دوئ به د زمکې وارثان شى، خو په چا چې لعنت وکړى د دُنيا نه به فنا شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13485, 'Psalms 37:23', 'Psalms', 37, 23, '&nbsp;کۀ مالِک خُدائ د نېکانو د کردار نه خوشحاله وى، هغه د هغوئ قدمونه سموى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13486, 'Psalms 37:24', 'Psalms', 37, 24, '&nbsp;کۀ تيندک وخورى نو وبه نۀ غورزيږى، ځکه چې مالِک خُدائ يې په خپلو لاسونو کښې اوچتوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13487, 'Psalms 37:25', 'Psalms', 37, 25, '&nbsp;ځوان ومه، بوډا شومه، صادقان مې بې‌اسرى ليدلى نۀ دى، او د هغوئ بچى مې د روټۍ په سوال ليدلى نۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13488, 'Psalms 37:26', 'Psalms', 37, 26, '&nbsp;په آزاد لاس ورکوى سخاوتونه نېکان، د دې برکتونه به وګورى د هغوئ بچيان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13489, 'Psalms 37:27', 'Psalms', 37, 27, '&nbsp;د بدو لاس په سر شئ، ښۀ کارونو ته ځان سپارئ، نو بيا به تاسو ټول عمر په دُنيا کښې اوسېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13490, 'Psalms 37:28', 'Psalms', 37, 28, '&nbsp;مالِک مينه کړى د اِنصاف سره او هغه به هيڅکله ‎پرې نۀ ږدى نېکان، هغه به دوئ وساتى په امان خو تباه به شى اولاد د بدکاران.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13491, 'Psalms 37:29', 'Psalms', 37, 29, '&nbsp;خو نېکانو ته به زمکه په ميراث کښې ورکړى، او صادقان به تر ابده په کښې سکونت کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13492, 'Psalms 37:30', 'Psalms', 37, 30, '&nbsp;نېکان خلق خبرې د حکمت کړى، او د هغوئ ژبه د اِنصاف خبرې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13493, 'Psalms 37:31', 'Psalms', 37, 31, '&nbsp;د خُدائ پاک قانون د هغۀ په زړۀ کښې دے، نو ځکه د سمې لارې نه نۀ ښوئيږى د هغۀ پښې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13494, 'Psalms 37:32', 'Psalms', 37, 32, '&nbsp;بدکاران صادقانو ته پټ ناست وى، ‎ او د هغوئ د قتلولو موقع لټوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13495, 'Psalms 37:33', 'Psalms', 37, 33, '&nbsp;مالِک خُدائ به يې هغوئ ته حواله نۀ کړى، په وخت د عدالت به صادقان مجرمان نۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13496, 'Psalms 37:34', 'Psalms', 37, 34, '&nbsp;او په مالِک خُدائ باندې توکل کوئ او د هغۀ د حُکمونو اِطاعت کوئ، هغه به تا اوچت کړى چې زمکه درله درکړى. او تۀ به وګورې چې بدعمله تباه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13497, 'Psalms 37:35', 'Psalms', 37, 35, '&nbsp;ما بې‌رحمه او ظالمان ليدلى دى، لکه څنګه چې شنه ونه په خپل ځائ کښې لوئيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13498, 'Psalms 37:36', 'Psalms', 37, 36, '&nbsp;خو چې دوباره مې وليدل، هغوئ د دُنيا نه تلى وُو، ما چې کله هغوئ لټول نو بيا نۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13499, 'Psalms 37:37', 'Psalms', 37, 37, '&nbsp;نېکانو او صادقانو ته وګوره، د دوئ آئنده به وى په خير سره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13500, 'Psalms 37:38', 'Psalms', 37, 38, '&nbsp;خو باغيان به ټول تباه شى، او د هغوئ نسل به نيست و نابود شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');